[
  {
    "statement": "There is limited specific information about the 20-year effects of municipal waste compost on soil fertility.",
    "citations": []
  },
  {
    "statement": "Adding municipal compost to semi-arid soils greatly reduced soil loss and water runoff.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "One study found mixed results for other waste composts regarding soil loss and water runoff.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "Adding compost to soil increases organic matter levels compared to soils without added compost.",
    "citations": [
      "1362"
    ]
  },
  {
    "statement": "Twelve replicated, controlled studies from Italy, Spain, Syria, Turkey, and the USA found more organic matter in soils with added compost.",
    "citations": [
      "1362"
    ]
  },
  {
    "statement": "Six studies found more nutrients in soils with added compost.",
    "citations": [
      "1362"
    ]
  },
  {
    "statement": "Six studies found more microbial biomass in soils with added compost compared to soils without added compost.",
    "citations": [
      "1362",
      "889"
    ]
  },
  {
    "statement": "Four studies found that soils with added compost were more stable than soils without added compost.",
    "citations": [
      "1362"
    ]
  },
  {
    "statement": "Six studies found more greenhouse gas emissions in soils with added compost compared to soils without added compost.",
    "citations": [
      "1362"
    ]
  },
  {
    "statement": "Applying a high rate of compost increased soil organic matter levels and microbial biomass.",
    "citations": [
      "889"
    ]
  },
  {
    "statement": "Studies demonstrate positive effects of compost on soil fertility indicators.",
    "citations": [
      "890",
      "1362",
      "889"
    ]
  },
  {
    "statement": "None of the available documents specifically address the effects of compost on soil fertility over a 20-year timeframe.",
    "citations": []
  }
]
